const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'G' },
      { kind: 'text', payload: 'N' },
      { kind: 'text', payload: 'f' },
      { kind: 'text', payload: '30°' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    function meas(i, dw, dh) {
      var m = metrics && metrics[i];
      var w = (m && typeof m.width === 'number' && m.width > 0) ? m.width : dw;
      var h = (m && typeof m.height === 'number' && m.height > 0) ? m.height : dh;
      return { w: w, h: h };
    }
    var tG = meas(0, 14, 16);
    var tN = meas(1, 14, 16);
    var tF = meas(2, 10, 18);
    var tA = meas(3, 26, 16);

    var rad = Math.PI / 6;
    var ux = Math.cos(rad), uy = -Math.sin(rad);
    var nx = -Math.sin(rad), ny = -Math.cos(rad);

    var groundY = 0.88 * H;
    var Ax = 0.12 * W, Ay = groundY;
    var L = 0.60 * W;
    var Bx = Ax + L * ux, By = Ay + L * uy;

    var Mx = Ax + (Bx - Ax) * 0.55;
    var My = Ay + (By - Ay) * 0.55;

    var s = 0.055 * Math.min(W, H);
    var P1x = Mx - ux * s, P1y = My - uy * s;
    var P2x = Mx + ux * s, P2y = My + uy * s;
    var P3x = P2x + nx * 2 * s, P3y = P2y + ny * 2 * s;
    var P4x = P1x + nx * 2 * s, P4y = P1y + ny * 2 * s;
    var Cx = (P1x + P2x + P3x + P4x) / 4;
    var Cy = (P1y + P2y + P3y + P4y) / 4;

    var GtipX = Cx, GtipY = Cy + 0.20 * H;
    var NtipX = Cx + nx * 0.24 * H, NtipY = Cy + ny * 0.24 * H;
    var FtipX = Cx + ux * 0.24 * H, FtipY = Cy + uy * 0.24 * H;

    var rAng = 0.115 * Math.min(W, H);

    var ground = visualSdk.polyline([[0.04 * W, groundY], [0.96 * W, groundY]]);
    var ramp = visualSdk.polyline([[Ax, Ay], [Bx, By], [Bx, groundY], [Ax, Ay]]);
    var slope = visualSdk.polyline([[Ax, Ay], [Bx, By]]);
    var block = visualSdk.polyline([[P1x, P1y], [P2x, P2y], [P3x, P3y], [P4x, P4y], [P1x, P1y]]);
    var angArc = visualSdk.arc(Ax, Ay, rAng, -rad, 0);
    var arrG = visualSdk.arrow(Cx, Cy, GtipX, GtipY);
    var arrN = visualSdk.arrow(Cx, Cy, NtipX, NtipY);
    var arrF = visualSdk.arrow(Cx, Cy, FtipX, FtipY);

    function lbl(text, cx, cy, tw) {
      return { type: 'label', text: text, x: cx - tw / 2, y: cy, fill: '#1f2d3d', fontSize: 17 };
    }
    var labG = lbl('G', GtipX + 16, GtipY + 4, tG.w);
    var labN = lbl('N', NtipX - 6, NtipY - 10, tN.w);
    var labF = lbl('f', FtipX + 14, FtipY - 8, tF.w);
    var angPx = Ax + (rAng + 20) * Math.cos(rad / 2);
    var angPy = Ay - (rAng + 20) * Math.sin(rad / 2);
    var labA = lbl('30°', angPx, angPy, tA.w);

    return {
      schemaVersion: 1,
      sceneId: 'incline-forces',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'ground', commands: ground },
        { id: 'ramp', commands: ramp },
        { id: 'slope', commands: slope },
        { id: 'block', commands: block },
        { id: 'angArc', commands: angArc },
        { id: 'arrG', commands: arrG },
        { id: 'arrN', commands: arrN },
        { id: 'arrF', commands: arrF }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'ramp', fill: '#eef2f7', stroke: '#8d9bad', strokeWidth: 1 },
        { type: 'path', pathId: 'ground', stroke: '#26354a', strokeWidth: 2 },
        { type: 'path', pathId: 'slope', stroke: '#26354a', strokeWidth: 2.5 },
        { type: 'path', pathId: 'block', fill: '#dce7f4', stroke: '#26354a', strokeWidth: 2 },
        { type: 'path', pathId: 'angArc', stroke: '#26354a', strokeWidth: 1.5 },
        { type: 'path', pathId: 'arrG', stroke: '#b3261e', strokeWidth: 2.5 },
        { type: 'path', pathId: 'arrN', stroke: '#1f5fa8', strokeWidth: 2.5 },
        { type: 'path', pathId: 'arrF', stroke: '#2e7d32', strokeWidth: 2.5 },
        labG, labN, labF, labA
      ] }
    };
  }
};
